// ─── Storage abstraction — IndexedDB by default, Supabase when authenticated ──

const DB_NAME        = 'atlantis-tools';
const STORE_NAME     = 'documents';
const SETTINGS_STORE = 'settings';
const DB_VERSION     = 2;

export interface SavedDoc {
  id:      string;   // numeric string for IDB, UUID for Supabase
  appId:   string;
  name:    string;
  content: string;
  savedAt: number;   // unix ms
}

// ─── Provider interface ───────────────────────────────────────────────────────

export interface StorageProvider {
  saveDoc(appId: string, name: string, content: string): Promise<string>;
  updateDoc(id: string, name: string, content: string): Promise<void>;
  listDocs(appId: string): Promise<SavedDoc[]>;
  deleteDoc(id: string): Promise<void>;
  putSetting(key: string, value: string): Promise<void>;
  getSetting(key: string): Promise<string | null>;
}

// ─── IndexedDB provider ───────────────────────────────────────────────────────

function openDB(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open(DB_NAME, DB_VERSION);
    req.onupgradeneeded = (e) => {
      const db = (e.target as IDBOpenDBRequest).result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        const store = db.createObjectStore(STORE_NAME, { keyPath: 'id', autoIncrement: true });
        store.createIndex('appId', 'appId', { unique: false });
      }
      if (!db.objectStoreNames.contains(SETTINGS_STORE)) {
        db.createObjectStore(SETTINGS_STORE, { keyPath: 'key' });
      }
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror   = () => reject(req.error);
  });
}

const idbProvider: StorageProvider = {
  async saveDoc(appId, name, content) {
    const db  = await openDB();
    const doc = { appId, name, content, savedAt: Date.now() };
    return new Promise((resolve, reject) => {
      const tx  = db.transaction(STORE_NAME, 'readwrite');
      const req = tx.objectStore(STORE_NAME).add(doc);
      req.onsuccess = () => resolve(String(req.result));
      req.onerror   = () => reject(req.error);
    });
  },

  async updateDoc(id, name, content) {
    const db = await openDB();
    return new Promise((resolve, reject) => {
      const tx    = db.transaction(STORE_NAME, 'readwrite');
      const store = tx.objectStore(STORE_NAME);
      const getReq = store.get(Number(id));
      getReq.onsuccess = () => {
        const existing = getReq.result;
        if (!existing) { reject(new Error('Doc not found')); return; }
        const putReq = store.put({ ...existing, name, content, savedAt: Date.now() });
        putReq.onsuccess = () => resolve();
        putReq.onerror   = () => reject(putReq.error);
      };
      getReq.onerror = () => reject(getReq.error);
    });
  },

  async listDocs(appId) {
    const db = await openDB();
    return new Promise((resolve, reject) => {
      const tx    = db.transaction(STORE_NAME, 'readonly');
      const index = tx.objectStore(STORE_NAME).index('appId');
      const req   = index.getAll(appId);
      req.onsuccess = () =>
        resolve((req.result as Array<SavedDoc & { id: number }>)
          .map((d) => ({ ...d, id: String(d.id) }))
          .reverse());
      req.onerror = () => reject(req.error);
    });
  },

  async deleteDoc(id) {
    const db = await openDB();
    return new Promise((resolve, reject) => {
      const tx  = db.transaction(STORE_NAME, 'readwrite');
      const req = tx.objectStore(STORE_NAME).delete(Number(id));
      req.onsuccess = () => resolve();
      req.onerror   = () => reject(req.error);
    });
  },

  async putSetting(key, value) {
    const db = await openDB();
    return new Promise((resolve, reject) => {
      const tx  = db.transaction(SETTINGS_STORE, 'readwrite');
      const req = tx.objectStore(SETTINGS_STORE).put({ key, value });
      req.onsuccess = () => resolve();
      req.onerror   = () => reject(req.error);
    });
  },

  async getSetting(key) {
    const db = await openDB();
    return new Promise((resolve, reject) => {
      const tx  = db.transaction(SETTINGS_STORE, 'readonly');
      const req = tx.objectStore(SETTINGS_STORE).get(key);
      req.onsuccess = () =>
        resolve(req.result ? (req.result as { key: string; value: string }).value : null);
      req.onerror = () => reject(req.error);
    });
  },
};

// ─── Active provider (swapped at runtime by the shell) ────────────────────────

let activeProvider: StorageProvider = idbProvider;

export function setStorageProvider(provider: StorageProvider | null) {
  activeProvider = provider ?? idbProvider;
}

// ─── Public API (delegates to active provider) ────────────────────────────────

export function saveDoc(appId: string, name: string, content: string): Promise<string> {
  return activeProvider.saveDoc(appId, name, content);
}

export function updateDoc(id: string, name: string, content: string): Promise<void> {
  return activeProvider.updateDoc(id, name, content);
}

export function listDocs(appId: string): Promise<SavedDoc[]> {
  return activeProvider.listDocs(appId);
}

export function deleteDoc(id: string): Promise<void> {
  return activeProvider.deleteDoc(id);
}

export function putSetting(key: string, value: string): Promise<void> {
  return activeProvider.putSetting(key, value);
}

export function getSetting(key: string): Promise<string | null> {
  return activeProvider.getSetting(key);
}

/**
 * Delete every setting whose key starts with `prefix` from the active provider.
 *
 * Used by the profile modal to flush `widget-cache:*` entries when the user
 * changes preferences — ageMode/interests affect what widgets should show,
 * and stale cache would otherwise hold the previous view for up to 5 min.
 *
 * Only implemented against the IDB provider's settings store. The Supabase
 * provider has no prefix-delete; for an authenticated user, the browser reload
 * after saving preferences is enough — their next fetch hits fresh data.
 */
export async function clearSettingsByPrefix(prefix: string): Promise<void> {
  try {
    const db = await openDB();
    await new Promise<void>((resolve, reject) => {
      const tx = db.transaction(SETTINGS_STORE, 'readwrite');
      const store = tx.objectStore(SETTINGS_STORE);
      const req = store.openCursor();
      req.onsuccess = () => {
        const cursor = req.result;
        if (!cursor) { resolve(); return; }
        if (String(cursor.key).startsWith(prefix)) cursor.delete();
        cursor.continue();
      };
      req.onerror = () => reject(req.error);
      tx.oncomplete = () => resolve();
    });
  } catch {
    /* IDB may not be available (private mode, etc) — best-effort clear */
  }
}
